-- Broaden micro preference prompts so they ask about situations, routines, and reasons.
-- This follows 069, expanding the same quality guardrail beyond stationery prompts.

START TRANSACTION;

CREATE TEMPORARY TABLE prompt_micro_preference_reframes (
    id VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci PRIMARY KEY,
    question_en TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
    question_ko TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
    tip TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL
);

INSERT INTO prompt_micro_preference_reframes (id, question_en, question_ko, tip) VALUES
    ('prompt-preference-2201', 'What makes breakfast easy to eat on a busy morning?', '바쁜 아침에 먹기 쉬운 아침 식사는 어떤 모습인가요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2202', 'How do you like to add protein or energy to breakfast?', '아침 식사에 단백질이나 에너지를 더하려면 보통 어떻게 하나요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2204', 'What do you add to a simple breakfast to make it more enjoyable?', '간단한 아침 식사를 더 즐겁게 만들기 위해 무엇을 더하나요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2205', 'What kind of quick breakfast helps you start the day?', '하루를 시작하는 데 도움이 되는 빠른 아침 식사는 무엇인가요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2206', 'What flavor makes a simple breakfast feel better?', '간단한 아침 식사를 더 기분 좋게 만드는 맛은 무엇인가요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2207', 'How do you make toast or a simple breakfast feel more complete?', '토스트나 간단한 아침 식사를 더 든든하게 만들려면 어떻게 하나요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2208', 'What simple meal works when you do not have much time?', '시간이 별로 없을 때 잘 맞는 간단한 식사는 무엇인가요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2213', 'What do you put on rice or a simple meal to make it satisfying?', '밥이나 간단한 식사를 더 만족스럽게 만들기 위해 무엇을 올리나요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2214', 'What would you eat on a quiet morning when you want something gentle?', '조용한 아침에 부담 없는 음식을 먹고 싶다면 무엇을 고르나요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2215', 'What quick meal helps when your morning starts late?', '아침이 늦게 시작된 날에는 어떤 빠른 식사가 도움이 되나요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2216', 'What small snack feels right during a short break?', '짧게 쉴 때 잘 맞는 작은 간식은 무엇인가요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2217', 'What crunchy snack do you reach for when you want a quick break?', '잠깐 쉬고 싶을 때 손이 가는 바삭한 간식은 무엇인가요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2218', 'What cold treat would you choose on a warm or tiring day?', '덥거나 피곤한 날에는 어떤 차가운 간식을 고르고 싶나요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2219', 'What sweet snack feels good after studying or working?', '공부나 일을 마친 뒤 기분 좋게 먹을 수 있는 달콤한 간식은 무엇인가요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2220', 'What small sweet would you choose when you want a little energy?', '조금 힘을 내고 싶을 때 어떤 작은 단 간식을 고르나요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2221', 'What would you pick from a convenience store during a busy day?', '바쁜 하루 중 편의점에 들른다면 무엇을 고르고 싶나요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2222', 'What simple snack is easy to share or eat while relaxing?', '쉬는 동안 먹거나 나누기 쉬운 간단한 간식은 무엇인가요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2223', 'What snack would you choose while watching a movie or show?', '영화나 영상을 볼 때 어떤 간식을 고르고 싶나요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2225', 'What drink snack feels refreshing during the day?', '하루 중 상쾌하게 마시거나 먹기 좋은 간식은 무엇인가요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2226', 'What sweet fruit flavor reminds you of a good break?', '좋은 휴식을 떠올리게 하는 달콤한 과일 맛은 무엇인가요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2227', 'What would you eat late at night when you want something small?', '늦은 밤에 조금만 먹고 싶을 때 무엇을 고르나요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2228', 'What salty snack fits a casual break, and why?', '가볍게 쉬는 시간에 잘 맞는 짭짤한 간식은 무엇인가요? 이유도 말해 주세요.', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2229', 'What soft snack would feel comforting after a long day?', '긴 하루 뒤에 위로가 될 만한 부드러운 간식은 무엇인가요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2230', 'What small treat would help you end the day in a good mood?', '하루를 기분 좋게 마무리하게 해 줄 작은 간식은 무엇인가요?', '음식 이름만 말하지 말고, 언제 먹는지와 그 순간에 잘 맞는 이유를 함께 말해 보세요.'),
    ('prompt-preference-2246', 'How do you choose what to wear when you want to feel comfortable and ready?', '편안하면서도 준비된 느낌을 받고 싶을 때 옷을 어떻게 고르나요?', '색이나 모양만 말하지 말고, 날씨나 장소, 기분 같은 상황을 함께 말해 보세요.'),
    ('prompt-preference-2247', 'What do you wear when you want to feel warm but relaxed?', '따뜻하면서도 편하게 있고 싶을 때 무엇을 입나요?', '색이나 모양만 말하지 말고, 날씨나 장소, 기분 같은 상황을 함께 말해 보세요.'),
    ('prompt-preference-2248', 'What small clothing detail can make an outfit feel more fun or comfortable?', '옷차림을 더 즐겁거나 편하게 만들어 주는 작은 요소는 무엇인가요?', '색이나 모양만 말하지 말고, 날씨나 장소, 기분 같은 상황을 함께 말해 보세요.'),
    ('prompt-preference-2249', 'What makes shoes comfortable for a normal day outside?', '평범한 외출 날에 신발이 편하게 느껴지려면 무엇이 중요할까요?', '색이나 모양만 말하지 말고, 날씨나 장소, 기분 같은 상황을 함께 말해 보세요.'),
    ('prompt-preference-2250', 'How do you prepare for strong sunlight when you go out?', '햇빛이 강한 날 외출할 때 어떻게 준비하나요?', '색이나 모양만 말하지 말고, 날씨나 장소, 기분 같은 상황을 함께 말해 보세요.'),
    ('prompt-preference-2251', 'What helps you stay warm on a cold day without feeling uncomfortable?', '추운 날 불편하지 않게 따뜻함을 유지하려면 무엇이 도움이 되나요?', '색이나 모양만 말하지 말고, 날씨나 장소, 기분 같은 상황을 함께 말해 보세요.'),
    ('prompt-preference-2252', 'What everyday accessory makes your outfit or routine feel easier?', '매일 쓰는 액세서리 중 옷차림이나 루틴을 더 편하게 해 주는 것은 무엇인가요?', '색이나 모양만 말하지 말고, 날씨나 장소, 기분 같은 상황을 함께 말해 보세요.'),
    ('prompt-preference-2253', 'What do you wear at home when you want your feet to feel comfortable?', '집에서 발이 편하게 느껴지려면 무엇을 신나요?', '색이나 모양만 말하지 말고, 날씨나 장소, 기분 같은 상황을 함께 말해 보세요.'),
    ('prompt-preference-2254', 'What helps you stay comfortable when it rains?', '비가 올 때 편하게 지내는 데 도움이 되는 것은 무엇인가요?', '색이나 모양만 말하지 말고, 날씨나 장소, 기분 같은 상황을 함께 말해 보세요.'),
    ('prompt-preference-2255', 'What makes bedtime clothes feel relaxing to you?', '잠잘 때 입는 옷이 편안하게 느껴지려면 무엇이 중요할까요?', '색이나 모양만 말하지 말고, 날씨나 장소, 기분 같은 상황을 함께 말해 보세요.'),
    ('prompt-preference-2256', 'What helps you keep your hair comfortable during a busy day?', '바쁜 하루 동안 머리를 편하게 유지하는 데 도움이 되는 것은 무엇인가요?', '색이나 모양만 말하지 말고, 날씨나 장소, 기분 같은 상황을 함께 말해 보세요.'),
    ('prompt-preference-2257', 'What do you bring or wear when the weather might change?', '날씨가 바뀔 수 있는 날에는 무엇을 챙기거나 입나요?', '색이나 모양만 말하지 말고, 날씨나 장소, 기분 같은 상황을 함께 말해 보세요.'),
    ('prompt-preference-2258', 'What kind of jacket works well for your everyday routine?', '일상 루틴에 잘 맞는 재킷은 어떤 점이 좋아야 하나요?', '색이나 모양만 말하지 말고, 날씨나 장소, 기분 같은 상황을 함께 말해 보세요.'),
    ('prompt-preference-2261', 'What helps you feel comfortable when you rest at home, and why?', '집에서 쉴 때 편안함을 느끼게 해 주는 것은 무엇인가요? 이유도 말해 주세요.', '물건 이름만 말하지 말고, 어떤 순간에 루틴이 편해지는지와 그 이유를 함께 말해 보세요.'),
    ('prompt-preference-2262', 'What makes your sleep or rest feel better at home?', '집에서 잠을 자거나 쉴 때 더 편하게 느끼게 해 주는 것은 무엇인가요?', '물건 이름만 말하지 말고, 어떤 순간에 루틴이 편해지는지와 그 이유를 함께 말해 보세요.'),
    ('prompt-preference-2263', 'What small part of your drink routine makes home feel more relaxing?', '집에서 마시는 음료 루틴 중 어떤 점이 더 편안하게 느껴지게 하나요?', '물건 이름만 말하지 말고, 어떤 순간에 루틴이 편해지는지와 그 이유를 함께 말해 보세요.'),
    ('prompt-preference-2265', 'How does lighting change the way you study, rest, or spend time in your room?', '방의 조명은 공부하거나 쉬거나 시간을 보내는 방식에 어떤 영향을 주나요?', '물건 이름만 말하지 말고, 어떤 순간에 루틴이 편해지는지와 그 이유를 함께 말해 보세요.'),
    ('prompt-preference-2266', 'What helps you remember to drink water at home, and when do you need it most?', '집에서 물 마시는 것을 기억하게 해 주는 것은 무엇인가요? 언제 가장 필요하나요?', '물건 이름만 말하지 말고, 어떤 순간에 루틴이 편해지는지와 그 이유를 함께 말해 보세요.'),
    ('prompt-preference-2267', 'What makes your desk feel easier to use during study or work?', '공부나 일을 할 때 책상을 더 쓰기 편하게 만드는 것은 무엇인가요?', '물건 이름만 말하지 말고, 어떤 순간에 루틴이 편해지는지와 그 이유를 함께 말해 보세요.'),
    ('prompt-preference-2268', 'What helps you sit comfortably when you read, study, or relax?', '책을 읽거나 공부하거나 쉴 때 편하게 앉는 데 도움이 되는 것은 무엇인가요?', '물건 이름만 말하지 말고, 어떤 순간에 루틴이 편해지는지와 그 이유를 함께 말해 보세요.'),
    ('prompt-preference-2269', 'How do you keep track of plans at home, and why does that method help?', '집에서 계획을 어떻게 확인하나요? 그 방법이 왜 도움이 되나요?', '물건 이름만 말하지 말고, 어떤 순간에 루틴이 편해지는지와 그 이유를 함께 말해 보세요.'),
    ('prompt-preference-2270', 'What helps your room feel cooler or more comfortable on warm days?', '더운 날 방을 더 시원하거나 편하게 느끼게 해 주는 것은 무엇인가요?', '물건 이름만 말하지 말고, 어떤 순간에 루틴이 편해지는지와 그 이유를 함께 말해 보세요.'),
    ('prompt-preference-2272', 'How do you keep everyday items easy to find at home?', '집에서 자주 쓰는 물건을 찾기 쉽게 두려면 어떻게 하나요?', '물건 이름만 말하지 말고, 어떤 순간에 루틴이 편해지는지와 그 이유를 함께 말해 보세요.'),
    ('prompt-preference-2274', 'What small thing makes your room feel more relaxing after a long day?', '긴 하루 뒤에 방을 더 편안하게 느끼게 해 주는 작은 것은 무엇인가요?', '물건 이름만 말하지 말고, 어떤 순간에 루틴이 편해지는지와 그 이유를 함께 말해 보세요.'),
    ('prompt-preference-2275', 'What do you like to keep near your bed, and how does it help your night routine?', '침대 근처에 두고 싶은 것은 무엇인가요? 밤 루틴에 어떻게 도움이 되나요?', '물건 이름만 말하지 말고, 어떤 순간에 루틴이 편해지는지와 그 이유를 함께 말해 보세요.'),
    ('prompt-preference-2276', 'What makes your hands feel cared for during the day?', '하루 중 손이 잘 관리되고 있다고 느끼게 해 주는 것은 무엇인가요?', '향이나 제품명만 말하지 말고, 언제 쓰는지와 사용 후 어떤 느낌이 드는지 함께 말해 보세요.'),
    ('prompt-preference-2277', 'What kind of clean feeling do you like after washing your hands?', '손을 씻은 뒤 어떤 깔끔한 느낌을 좋아하나요?', '향이나 제품명만 말하지 말고, 언제 쓰는지와 사용 후 어떤 느낌이 드는지 함께 말해 보세요.'),
    ('prompt-preference-2278', 'What makes washing your hair feel refreshing or relaxing?', '머리를 감는 시간이 상쾌하거나 편안하게 느껴지려면 무엇이 중요한가요?', '향이나 제품명만 말하지 말고, 언제 쓰는지와 사용 후 어떤 느낌이 드는지 함께 말해 보세요.'),
    ('prompt-preference-2279', 'What do you use when your lips feel dry, and why?', '입술이 건조할 때 무엇을 사용하나요? 이유도 말해 주세요.', '향이나 제품명만 말하지 말고, 언제 쓰는지와 사용 후 어떤 느낌이 드는지 함께 말해 보세요.'),
